definition:
CREATE OR REPLACE FUNCTION public.admin_kick_member(target_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_current_user_admin() then
    raise exception '관리자만 회원을 퇴장시킬 수 있습니다.';
  end if;

  if target_member_id = auth.uid() then
    raise exception '관리자 본인은 퇴장시킬 수 없습니다.';
  end if;

  if exists (
    select 1 from public.profiles
    where id = target_member_id and role = 'admin'
  ) then
    raise exception '다른 관리자는 퇴장시킬 수 없습니다.';
  end if;

  update public.profiles
  set approval_status = 'rejected'
  where id = target_member_id;

  update public.members
  set status = 'rejected'
  where id = target_member_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.announce_event_winner_to_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.events%rowtype;
  v_winner_name text;
  v_admin_id uuid;
  v_game_name text;
begin
  select * into v_event
  from public.events
  where id = new.event_id;

  if not found then
    return new;
  end if;

  select nickname into v_winner_name
  from public.profiles
  where id = new.member_id;

  select id into v_admin_id
  from public.profiles
  where role = 'admin'
    and approval_status = 'approved'
  order by created_at asc
  limit 1;

  if v_admin_id is null then
    return new;
  end if;

  v_game_name := public.event_type_korean(v_event.event_type);

  insert into public.group_messages(
    room_id,
    member_id,
    message_type,
    content,
    is_deleted,
    created_at
  )
  values (
    v_event.room_id,
    v_admin_id,
    'text',
    '🎉 축하드립니다!' || E'\n\n' ||
    '이번 ' || v_game_name || ' 이벤트 당첨자는' || E'\n' ||
    '🏆 ' || coalesce(v_winner_name, 'VIP 회원') || ' 님입니다!' || E'\n\n' ||
    '🎁 상품은 1:1 문의로 즉시 지급됩니다.' || E'\n' ||
    '당첨을 진심으로 축하드립니다! ✨',
    false,
    now()
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_daily_auto_events(target_date date DEFAULT ((now() AT TIME ZONE 'Asia/Seoul'::text))::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare

  room_uuid uuid :=
    '0a495a02-bcb8-4e38-b3ef-4e7059c2a883';

  i integer;

  event_start timestamp;
  event_end timestamp;

  selected_type text;
  selected_title text;
  selected_description text;

  created_event_id uuid;

begin

  for i in 0..19 loop

    event_start :=
      target_date::timestamp
      + time '11:00'
      + (interval '435 minutes' * i / 19.0);

    event_end :=
      event_start + interval '15 minutes';


    case (i % 7)

      when 0 then

        selected_type := 'gift_box';

        selected_title :=
          '🎁 랜덤 선물상자';

        selected_description :=
          '4개의 선물상자 중 하나를 선택하세요. 당첨 상자를 선택한 회원이 여러 명이면 그중 1명을 무작위로 선정합니다.';


      when 1 then

        selected_type := 'number';

        selected_title :=
          '🎯 숫자 맞히기';

        selected_description :=
          '1부터 100까지 숫자 하나를 선택하세요. 정답자가 여러 명이면 1명을 무작위 선정하며, 정답자가 없으면 가장 가까운 숫자를 선택한 회원 중 1명을 선정합니다.';


      when 2 then

        selected_type := 'roulette';

        selected_title :=
          '🎰 행운의 룰렛';

        selected_description :=
          '룰렛을 돌려 이벤트에 응모하세요. 회차 종료 후 실제 참여자 중 1명을 서버에서 무작위 선정합니다.';


      when 3 then

        selected_type := 'first_come';

        selected_title :=
          '⚡ 선착순 미션';

        selected_description :=
          '이벤트 시작 후 가장 먼저 정상 접수된 회원 1명이 즉시 당첨됩니다. 서버 접수시간을 기준으로 판정합니다.';


      when 4 then

        selected_type := 'quiz';

        selected_title :=
          '🧩 오늘의 퀴즈';

        selected_description :=
          '4개의 보기 중 정답 하나를 선택하세요. 정답자가 여러 명이면 정답자 중 1명을 무작위로 선정합니다.';


      when 5 then

        selected_type := 'draw';

        selected_title :=
          '🎟️ 자동 추첨';

        selected_description :=
          '한 번 응모하면 참여 완료됩니다. 회차 종료 후 실제 응모자 중 1명을 무작위로 선정합니다.';


      else

        selected_type := 'attendance';

        selected_title :=
          '📅 누적 출석';

        selected_description :=
          '출석 버튼을 눌러 오늘의 출석 기록을 남기세요. 해당 회차 출석자 중 1명을 무작위로 선정합니다.';

    end case;


    insert into public.events (
      room_id,
      created_by,
      title,
      description,
      prize,
      event_type,
      status,
      winner_count,
      starts_at,
      ends_at,
      schedule_date,
      round_number,
      auto_event
    )

    values (
      room_uuid,
      null,
      selected_title,
      selected_description,
      'VIP EVENT 당첨',
      selected_type,
      'scheduled',
      1,

      event_start at time zone 'Asia/Seoul',
      event_end at time zone 'Asia/Seoul',

      target_date,
      i + 1,
      true
    )

    on conflict do nothing;

  end loop;


  -- 오늘 생성되어 있는 모든 자동 이벤트에
  -- 게임 설정을 붙임.
  for created_event_id in

    select id
    from public.events

    where auto_event = true
      and schedule_date = target_date

  loop

    perform public.setup_event_game(
      created_event_id
    );

  end loop;

end;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_admin_chat()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  admin_id uuid;
  chat_id uuid;
begin
  -- 승인된 관리자 찾기
  select id into admin_id
  from public.profiles
  where role = 'admin'
    and approval_status = 'approved'
  limit 1;

  if admin_id is null then
    raise exception '관리자 계정을 찾을 수 없습니다.';
  end if;

  -- 관리자가 자기 자신과 상담방을 만드는 것은 막기
  if auth.uid() = admin_id then
    raise exception '관리자 계정입니다.';
  end if;

  -- 승인된 회원만 사용 가능
  if not exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and approval_status = 'approved'
  ) then
    raise exception '승인된 회원만 이용할 수 있습니다.';
  end if;

  -- 기존 상담방 찾기
  select id into chat_id
  from public.private_chats
  where member_id = auth.uid()
    and operator_id = admin_id
  limit 1;

  -- 없으면 새 상담방 생성
  if chat_id is null then
    insert into public.private_chats (
      member_id,
      operator_id,
      status
    )
    values (
      auth.uid(),
      admin_id,
      'open'
    )
    returning id into chat_id;
  end if;

  return chat_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.join_auto_event(target_event_id uuid, submitted_answer text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare

  target_event public.events%rowtype;

  secret_value text;

  quiz_correct integer;

  submitted_number integer;

  submitted_box integer;

begin

  -- 로그인 확인
  if auth.uid() is null then

    raise exception
      '로그인이 필요합니다.';

  end if;


  -- 승인 회원 확인
  if not exists (

    select 1

    from public.profiles

    where id = auth.uid()
      and approval_status = 'approved'

  ) then

    raise exception
      '승인된 회원만 참여할 수 있습니다.';

  end if;


  -- 이벤트 잠금
  select *
  into target_event

  from public.events

  where id = target_event_id

  for update;


  if not found then

    raise exception
      '이벤트를 찾을 수 없습니다.';

  end if;


  -- 서버시간 기준
  if now() < target_event.starts_at then

    return jsonb_build_object(
      'success', false,
      'message',
      '아직 시작되지 않은 이벤트입니다.'
    );

  end if;


  if now() >= target_event.ends_at then

    return jsonb_build_object(
      'success', false,
      'message',
      '이미 종료된 이벤트입니다.'
    );

  end if;


  if target_event.status = 'completed' then

    return jsonb_build_object(
      'success', false,
      'message',
      '이미 종료된 이벤트입니다.'
    );

  end if;


  -- 중복 참여 확인
  if exists (

    select 1

    from public.event_entries

    where event_id = target_event_id
      and member_id = auth.uid()

  ) then

    return jsonb_build_object(
      'success', false,
      'message',
      '이미 참여한 이벤트입니다.'
    );

  end if;


  -- 게임 설정 보장
  perform public.setup_event_game(
    target_event_id
  );


  select secret_answer
  into secret_value

  from public.event_game_secrets

  where event_id = target_event_id;


  -- =====================================================
  -- 숫자 맞히기
  -- =====================================================

  if target_event.event_type = 'number' then

    begin

      submitted_number :=
        trim(submitted_answer)::integer;

    exception when others then

      return jsonb_build_object(
        'success', false,
        'message',
        '1부터 100까지 숫자를 선택해주세요.'
      );

    end;


    if submitted_number < 1
       or submitted_number > 100 then

      return jsonb_build_object(
        'success', false,
        'message',
        '숫자는 1부터 100까지만 선택할 수 있습니다.'
      );

    end if;


    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      submitted_number::text,

      submitted_number::text =
        secret_value,

      '숫자 선택 완료',
      now()
    );


    return jsonb_build_object(
      'success', true,
      'message',
      submitted_number ||
      '번으로 참여가 완료되었습니다.'
    );


  -- =====================================================
  -- 선물상자
  -- =====================================================

  elsif target_event.event_type = 'gift_box' then

    begin

      submitted_box :=
        trim(submitted_answer)::integer;

    exception when others then

      return jsonb_build_object(
        'success', false,
        'message',
        '선물상자를 선택해주세요.'
      );

    end;


    if submitted_box < 1
       or submitted_box > 4 then

      return jsonb_build_object(
        'success', false,
        'message',
        '1번부터 4번까지의 선물상자 중 하나를 선택해주세요.'
      );

    end if;


    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      submitted_box::text,

      submitted_box::text =
        secret_value,

      submitted_box ||
        '번 선물상자 선택 완료',

      now()
    );


    return jsonb_build_object(
      'success', true,
      'message',
      submitted_box ||
      '번 선물상자를 선택했습니다.'
    );


  -- =====================================================
  -- 퀴즈
  -- =====================================================

  elsif target_event.event_type = 'quiz' then

    begin

      submitted_number :=
        trim(submitted_answer)::integer;

    exception when others then

      return jsonb_build_object(
        'success', false,
        'message',
        '퀴즈 정답을 선택해주세요.'
      );

    end;


    if submitted_number < 1
       or submitted_number > 4 then

      return jsonb_build_object(
        'success', false,
        'message',
        '보기 중 하나를 선택해주세요.'
      );

    end if;


    select q.correct_option
    into quiz_correct

    from public.event_quiz_bank q

    where q.id = secret_value::uuid;


    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      submitted_number::text,

      submitted_number =
        quiz_correct,

      case

        when submitted_number =
          quiz_correct

        then '정답 제출 완료'

        else '답안 제출 완료'

      end,

      now()
    );


    -- 진행 중에는 정답 여부를 바로 공개하지 않음.
    return jsonb_build_object(
      'success', true,
      'message',
      '답안 제출이 완료되었습니다. 정답과 결과는 회차 종료 후 공개됩니다.'
    );


  -- =====================================================
  -- 선착순
  -- 이벤트 row를 FOR UPDATE로 잠근 상태이므로
  -- 동시에 눌러도 먼저 DB에 들어온 요청 1명만 당첨
  -- =====================================================

  elsif target_event.event_type = 'first_come' then


    if exists (

      select 1

      from public.event_winners

      where event_id =
        target_event_id

    ) then

      return jsonb_build_object(
        'success', false,
        'message',
        '선착순 당첨자가 이미 결정되었습니다.'
      );

    end if;


    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      null,
      true,
      '선착순 1위',
      now()
    );


    insert into public.event_winners (
      event_id,
      member_id,
      rank
    )

    values (
      target_event_id,
      auth.uid(),
      1
    )

    on conflict (event_id)
    do nothing;


    update public.events

    set
      status = 'completed',
      completed_at = now()

    where id = target_event_id;


    return jsonb_build_object(
      'success', true,
      'winner', true,
      'message',
      '축하합니다! 가장 먼저 참여하여 선착순 당첨자로 선정되었습니다.'
    );


  -- =====================================================
  -- 룰렛
  -- =====================================================

  elsif target_event.event_type = 'roulette' then

    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      'roulette',
      null,
      '룰렛 참여 완료',
      now()
    );


    return jsonb_build_object(
      'success', true,
      'message',
      '룰렛 참여가 완료되었습니다. 회차 종료 후 참여자 중 1명이 무작위로 선정됩니다.'
    );


  -- =====================================================
  -- 자동 추첨
  -- =====================================================

  elsif target_event.event_type = 'draw' then

    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      null,
      null,
      '자동 추첨 응모 완료',
      now()
    );


    return jsonb_build_object(
      'success', true,
      'message',
      '응모가 완료되었습니다. 회차 종료 후 참여자 중 1명이 무작위로 선정됩니다.'
    );


  -- =====================================================
  -- 출석
  -- =====================================================

  elsif target_event.event_type = 'attendance' then

    insert into public.event_entries (
      event_id,
      member_id,
      answer,
      is_correct,
      result_text,
      submitted_at
    )

    values (
      target_event_id,
      auth.uid(),
      null,
      null,
      '출석 완료',
      now()
    );


    insert into public.attendance_records (
      event_id,
      member_id,
      attendance_date
    )

    values (
      target_event_id,
      auth.uid(),
      (now() at time zone 'Asia/Seoul')::date
    )

    on conflict do nothing;


    return jsonb_build_object(
      'success', true,
      'message',
      '출석이 완료되었습니다.'
    );


  else

    return jsonb_build_object(
      'success', false,
      'message',
      '지원하지 않는 이벤트입니다.'
    );

  end if;

end;
$function$

CREATE OR REPLACE FUNCTION public.set_group_chat_frozen(target_room_id uuid, frozen boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin' and approval_status = 'approved'
  ) then
    raise exception '관리자만 변경할 수 있습니다.';
  end if;

  insert into public.room_chat_settings(room_id, is_frozen, updated_at, updated_by)
  values(target_room_id, frozen, now(), auth.uid())
  on conflict (room_id) do update
  set is_frozen = excluded.is_frozen,
      updated_at = now(),
      updated_by = auth.uid();

  return frozen;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_avatar(new_avatar text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new_avatar not in (
    'vip_01',
    'vip_02',
    'vip_03',
    'vip_04',
    'vip_05',
    'vip_06'
  ) then
    raise exception 'Invalid avatar';
  end if;

  update public.profiles
  set avatar = new_avatar
  where id = auth.uid()
    and approval_status = 'approved';

  if not found then
    raise exception 'Approved profile not found';
  end if;
end;
$function$
